class Solution:
    def smallestString(self, s):
        n = len(s)
        best = s
        for k in range(1, n + 1):
            cand = s[:k][::-1] + s[k:]
            if cand < best:
                best = cand
            cand = s[:n - k] + s[n - k:][::-1]
            if cand < best:
                best = cand
        return best

