class Solution {
public:
    string smallestString(string s) {
        int n = s.size();
        string best = s;
        for (int k = 1; k <= n; k++) {
            string c = s;
            reverse(c.begin(), c.begin() + k);
            best = min(best, c);
            c = s;
            reverse(c.end() - k, c.end());
            best = min(best, c);
        }
        return best;
    }
};

c.java:
class Solution {
    public String smallestString(String s) {
        int n = s.length();
        String best = s;
        for (int k = 1; k <= n; k++) {
            StringBuilder sb = new StringBuilder(s.substring(0, k)).reverse();
            String c = sb.append(s.substring(k)).toString();
            if (c.compareTo(best) < 0) best = c;
            sb = new StringBuilder(s.substring(n - k)).reverse();
            c = s.substring(0, n - k) + sb;
            if (c.compareTo(best) < 0) best = c;
        }
        return best;
    }
}

